'use strict';
var isArray = require('isarray');
var Buffer = require('safe-buffer').Buffer;
var pna = require('process-nextick-args');
var inherits = require('inherits');
var deprecate = require('util-deprecate');

function Shape(name) {
  this.name = name;
}
Shape.prototype.describe = function () {
  return 'shape ' + this.name;
};

function Square(side) {
  Shape.call(this, 'square');
  this.side = side;
}
inherits(Square, Shape);
Square.prototype.area = function () {
  return this.side * this.side;
};

var oldArea = deprecate(function (side) {
  return side * side;
}, 'oldArea() is deprecated');

exports.kinds = function (values) {
  return values.map(function (v) {
    return isArray(v) ? 'array' : typeof v;
  }).join(',');
};

exports.encode = function (text) {
  var buf = Buffer.from(text, 'utf8');
  return buf.toString('hex') + ' ' + Buffer.alloc(3, 1).toString('base64') + ' ' + Buffer.byteLength(text);
};

exports.later = function (label, done) {
  pna.nextTick(function (a, b) {
    done(label + ':' + a + '+' + b);
  }, 1, 2);
};

exports.square = function (side) {
  var s = new Square(side);
  return s.describe() + ' ' + s.area() + ' ' + (Square.super_ === Shape);
};

exports.oldArea = oldArea;
